import { Schema } from "effect";

/** A recipient or sender address. Only its shape is checked; the provider is the judge of deliverability. */
export const EmailAddress = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/)),
  Schema.brand("EmailAddress"),
);
export type EmailAddress = typeof EmailAddress.Type;

/** Identifies one transactional send, unique within its Organization. Retries reuse it. */
export const SendId = Schema.NonEmptyString.pipe(Schema.brand("SendId"));
export type SendId = typeof SendId.Type;

/** "You've been added to <Team> by <Lead>." Sent when a Lead adds a Person to a Team. */
export const AddedToTeam = Schema.TaggedStruct("AddedToTeam", {
  teamName: Schema.NonEmptyString,
  leadName: Schema.NonEmptyString,
  signInUrl: Schema.String.pipe(Schema.check(Schema.isStartingWith("https://"))),
});
export type AddedToTeam = typeof AddedToTeam.Type;

/** A rating question prompt and range labels for one-tap email rating links. */
export const EmailRatingQuestion = Schema.Struct({
  text: Schema.String,
  lowLabel: Schema.String,
  highLabel: Schema.String,
});
export type EmailRatingQuestion = typeof EmailRatingQuestion.Type;

/** One Invitation email with one-tap rating links (ADR 0005, 0007). */
export const InvitationEmail = Schema.TaggedStruct("InvitationEmail", {
  pulseName: Schema.NonEmptyString,
  anonymityStatement: Schema.NonEmptyString,
  token: Schema.NonEmptyString,
  baseUrl: Schema.String.pipe(Schema.check(Schema.isStartingWith("https://"))),
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
});
export type InvitationEmail = typeof InvitationEmail.Type;

/** A reminder email for an open round with one-click unsubscribe headers (RFC 8058). */
export const ReminderEmail = Schema.TaggedStruct("ReminderEmail", {
  pulseName: Schema.NonEmptyString,
  token: Schema.NonEmptyString,
  baseUrl: Schema.String.pipe(Schema.check(Schema.isStartingWith("https://"))),
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  unsubscribeUrl: Schema.String.pipe(Schema.check(Schema.isStartingWith("https://"))),
});
export type ReminderEmail = typeof ReminderEmail.Type;

/** A results-ready notice email sent when a Round closes and results are shared. */
export const ResultsReadyEmail = Schema.TaggedStruct("ResultsReadyEmail", {
  pulseName: Schema.NonEmptyString,
  teamName: Schema.NonEmptyString,
  resultsUrl: Schema.String.pipe(Schema.check(Schema.isStartingWith("https://"))),
  responseRatePercent: Schema.Int,
});
export type ResultsReadyEmail = typeof ResultsReadyEmail.Type;

/**
 * What to say, without how it looks. A send stores this and the Queue consumer renders it,
 * so a template fix reaches mail that is still waiting to be sent.
 */
export const TransactionalEmail = Schema.Union([
  AddedToTeam,
  InvitationEmail,
  ReminderEmail,
  ResultsReadyEmail,
]);
export type TransactionalEmail = typeof TransactionalEmail.Type;

/** A rendered message: the HTML part and the plain-text part always travel together. */
export interface RenderedEmail {
  readonly subject: string;
  readonly html: string;
  readonly text: string;
  readonly headers?: Readonly<Record<string, string>> | undefined;
}

/** What an `EmailSender` delivers. The sender address is the adapter's configuration. */
export interface OutgoingEmail extends RenderedEmail {
  readonly to: EmailAddress;
}
export { EmailTemplatesLive, renderEmail } from "./render.tsx";
import { message } from "./messages/index.ts";

/** What the lead will and will not see, with the Team's minimum group size N (SPEC 5.2, ADR 0004). */
export const anonymityStatement = (minimumGroupSize: number): string =>
  message("invitation.anonymity", { n: minimumGroupSize });
import { describe, expect, it } from "@effect/vitest";
import { anonymityStatement } from "./index.ts";

describe("anonymityStatement", () => {
  it("states the minimum group size and that the lead never sees who answered what", () => {
    const statement = anonymityStatement(4);
    expect(statement).toContain("at least 4 people");
    expect(statement).toContain("never who answered what");
    expect(statement).toContain("Your name is never stored with your answers.");
  });
});
import type { InvitationEmail as InvitationEmailData } from "@surveybeat/domain";
import { Button, Heading, Link, Section, Text } from "react-email";
import { colors, Layout, textLayout } from "./Layout.tsx";
import { message } from "./messages/index.ts";

export const subject = (email: InvitationEmailData): string =>
  message("invitation.subject", { pulse: email.pulseName });

export function InvitationEmailComponent({ email }: { email: InvitationEmailData }) {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  return (
    <Layout
      preview={message("invitation.preview", { pulse: email.pulseName })}
      reason={message("invitation.reason")}
    >
      <Heading
        as="h1"
        className="sb-text"
        style={{ color: colors.text, fontSize: "22px", lineHeight: "30px", margin: "0 0 12px" }}
      >
        {email.pulseName}
      </Heading>

      <Text
        className="sb-muted"
        style={{ color: colors.muted, fontSize: "14px", lineHeight: "20px", margin: "0 0 20px" }}
      >
        {email.anonymityStatement}
      </Text>

      {email.ratingQuestion && (
        <Section style={{ margin: "20px 0" }}>
          <Text
            className="sb-text"
            style={{ color: colors.text, fontSize: "16px", fontWeight: 600, margin: "0 0 12px" }}
          >
            {email.ratingQuestion.text}
          </Text>
          <div style={{ display: "flex", gap: "8px", margin: "12px 0", flexWrap: "wrap" }}>
            {[1, 2, 3, 4, 5].map((val) => {
              const label =
                val === 1
                  ? `1 · ${email.ratingQuestion?.lowLabel}`
                  : val === 5
                    ? `5 · ${email.ratingQuestion?.highLabel}`
                    : `${val}`;
              return (
                <Button
                  key={val}
                  className="sb-button"
                  href={`${email.baseUrl}/a#t=${email.token}&v=${val}`}
                  style={{
                    backgroundColor: colors.card,
                    border: `1px solid ${colors.border}`,
                    borderRadius: "6px",
                    color: colors.text,
                    fontSize: "14px",
                    fontWeight: 500,
                    padding: "8px 14px",
                    textDecoration: "none",
                  }}
                >
                  {label}
                </Button>
              );
            })}
          </div>
        </Section>
      )}

      <div style={{ margin: "24px 0" }}>
        <Button
          className="sb-button"
          href={openUrl}
          style={{
            backgroundColor: colors.accent,
            borderRadius: "8px",
            color: colors.accentText,
            fontSize: "16px",
            fontWeight: 600,
            padding: "12px 20px",
            textDecoration: "none",
          }}
        >
          {message("invitation.openCheckIn")}
        </Button>
      </div>

      {email.actions.length > 0 && (
        <Section style={{ margin: "24px 0 16px" }}>
          <Text
            className="sb-text"
            style={{ color: colors.text, fontSize: "14px", fontWeight: 600, margin: "0 0 8px" }}
          >
            {message("invitation.actionsHeading")}
          </Text>
          <ul style={{ margin: 0, paddingLeft: "20px", color: colors.muted, fontSize: "14px" }}>
            {email.actions.slice(0, 3).map((act, i) => (
              <li key={i}>{act}</li>
            ))}
          </ul>
        </Section>
      )}

      <Section style={{ borderTop: `1px solid ${colors.border}`, margin: "24px 0 0", paddingTop: "16px" }}>
        <Text className="sb-muted" style={{ color: colors.muted, fontSize: "12px", margin: "0 0 4px" }}>
          <Link href={deliveryUrl} style={{ color: colors.accent, textDecoration: "underline" }}>
            {message("invitation.changeWhen")}
          </Link>
        </Text>
        <Text className="sb-muted" style={{ color: colors.muted, fontSize: "12px", margin: 0 }}>
          {message("invitation.personalNotice")}
        </Text>
      </Section>
    </Layout>
  );
}

export const text = (email: InvitationEmailData): string => {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  const ratingLines: Array<string> = [];
  if (email.ratingQuestion) {
    ratingLines.push(email.ratingQuestion.text, "");
    for (let val = 1; val <= 5; val++) {
      const label =
        val === 1
          ? `1 (${email.ratingQuestion.lowLabel})`
          : val === 5
            ? `5 (${email.ratingQuestion.highLabel})`
            : `${val}`;
      ratingLines.push(`${label}: ${email.baseUrl}/a#t=${email.token}&v=${val}`);
    }
    ratingLines.push("");
  }

  const actionLines: Array<string> = [];
  if (email.actions.length > 0) {
    actionLines.push(message("invitation.actionsHeading"));
    for (const act of email.actions.slice(0, 3)) {
      actionLines.push(`• ${act}`);
    }
    actionLines.push("");
  }

  return textLayout(
    [
      email.pulseName,
      "",
      email.anonymityStatement,
      "",
      ...ratingLines,
      `${message("invitation.openCheckIn")}: ${openUrl}`,
      "",
      ...actionLines,
      `${message("invitation.changeWhen")}: ${deliveryUrl}`,
      message("invitation.personalNotice"),
    ],
    message("invitation.reason"),
  );
};
