import { EmailTemplates, type RenderedEmail, type TransactionalEmail } from "@surveybeat/domain";
import { Effect, Layer } from "effect";
import { render } from "react-email";
import * as AddedToTeam from "./AddedToTeam.tsx";
import * as InvitationEmail from "./InvitationEmail.tsx";
import * as ReminderEmail from "./ReminderEmail.tsx";
import * as ResultsReadyEmail from "./ResultsReadyEmail.tsx";

/** A subject is one header line: names with line breaks must not start another header. */
const oneLine = (subject: string) => subject.replace(/\s*[\r\n]+\s*/g, " ");

/** Renders the HTML and plain-text parts. Adding a `TransactionalEmail` variant fails to compile here. */
export const renderEmail = async (email: TransactionalEmail): Promise<RenderedEmail> => {
  switch (email._tag) {
    case "AddedToTeam":
      return {
        subject: oneLine(AddedToTeam.subject(email)),
        html: await render(<AddedToTeam.AddedToTeamEmail email={email} />),
        text: AddedToTeam.text(email),
      };
    case "InvitationEmail":
      return {
        subject: oneLine(InvitationEmail.subject(email)),
        html: await render(<InvitationEmail.InvitationEmailComponent email={email} />),
        text: InvitationEmail.text(email),
      };
    case "ReminderEmail":
      return {
        subject: oneLine(ReminderEmail.subject(email)),
        html: await render(<ReminderEmail.ReminderEmailComponent email={email} />),
        text: ReminderEmail.text(email),
        headers: {
          "List-Unsubscribe": `<${email.unsubscribeUrl}>`,
          "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
        },
      };
    case "ResultsReadyEmail":
      return {
        subject: oneLine(ResultsReadyEmail.subject(email)),
        html: await render(<ResultsReadyEmail.ResultsReadyEmailComponent email={email} />),
        text: ResultsReadyEmail.text(email),
      };
  }
};

/** The domain's `EmailTemplates`, rendered with React Email. A render failure is a defect. */
export const EmailTemplatesLive = Layer.succeed(EmailTemplates, {
  render: (email) => Effect.promise(() => renderEmail(email)),
});
import type { ReminderEmail as ReminderEmailData } from "@surveybeat/domain";
import { Button, Heading, Link, Section, Text } from "react-email";
import { colors, Layout, textLayout } from "./Layout.tsx";
import { message } from "./messages/index.ts";

export const subject = (email: ReminderEmailData): string =>
  message("reminder.subject", { pulse: email.pulseName });

export function ReminderEmailComponent({ email }: { email: ReminderEmailData }) {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  return (
    <Layout
      preview={message("reminder.preview", { pulse: email.pulseName })}
      reason={message("invitation.reason")}
    >
      <Heading
        as="h1"
        className="sb-text"
        style={{ color: colors.text, fontSize: "22px", lineHeight: "30px", margin: "0 0 12px" }}
      >
        {message("reminder.heading", { pulse: email.pulseName })}
      </Heading>

      <Text
        className="sb-text"
        style={{ color: colors.text, fontSize: "16px", lineHeight: "24px", margin: "0 0 16px" }}
      >
        {message("reminder.body")}
      </Text>

      {email.ratingQuestion && (
        <Section style={{ margin: "20px 0" }}>
          <Text
            className="sb-text"
            style={{ color: colors.text, fontSize: "16px", fontWeight: 600, margin: "0 0 12px" }}
          >
            {email.ratingQuestion.text}
          </Text>
          <div style={{ display: "flex", gap: "8px", margin: "12px 0", flexWrap: "wrap" }}>
            {[1, 2, 3, 4, 5].map((val) => {
              const label =
                val === 1
                  ? `1 · ${email.ratingQuestion?.lowLabel}`
                  : val === 5
                    ? `5 · ${email.ratingQuestion?.highLabel}`
                    : `${val}`;
              return (
                <Button
                  key={val}
                  className="sb-button"
                  href={`${email.baseUrl}/a#t=${email.token}&v=${val}`}
                  style={{
                    backgroundColor: colors.card,
                    border: `1px solid ${colors.border}`,
                    borderRadius: "6px",
                    color: colors.text,
                    fontSize: "14px",
                    fontWeight: 500,
                    padding: "8px 14px",
                    textDecoration: "none",
                  }}
                >
                  {label}
                </Button>
              );
            })}
          </div>
        </Section>
      )}

      <div style={{ margin: "24px 0" }}>
        <Button
          className="sb-button"
          href={openUrl}
          style={{
            backgroundColor: colors.accent,
            borderRadius: "8px",
            color: colors.accentText,
            fontSize: "16px",
            fontWeight: 600,
            padding: "12px 20px",
            textDecoration: "none",
          }}
        >
          {message("invitation.openCheckIn")}
        </Button>
      </div>

      {email.actions && email.actions.length > 0 && (
        <Section style={{ margin: "24px 0 16px" }}>
          <Text
            className="sb-text"
            style={{ color: colors.text, fontSize: "14px", fontWeight: 600, margin: "0 0 8px" }}
          >
            {message("invitation.actionsHeading")}
          </Text>
          <ul style={{ margin: 0, paddingLeft: "20px", color: colors.muted, fontSize: "14px" }}>
            {email.actions.slice(0, 3).map((act, i) => (
              <li key={i}>{act}</li>
            ))}
          </ul>
        </Section>
      )}

      <Section style={{ borderTop: `1px solid ${colors.border}`, margin: "24px 0 0", paddingTop: "16px" }}>
        <Text className="sb-muted" style={{ color: colors.muted, fontSize: "12px", margin: "0 0 4px" }}>
          <Link href={deliveryUrl} style={{ color: colors.accent, textDecoration: "underline" }}>
            {message("invitation.changeWhen")}
          </Link>
          {" · "}
          <Link href={email.unsubscribeUrl} style={{ color: colors.muted, textDecoration: "underline" }}>
            {message("reminder.unsubscribe")}
          </Link>
        </Text>
        <Text className="sb-muted" style={{ color: colors.muted, fontSize: "12px", margin: 0 }}>
          {message("invitation.personalNotice")}
        </Text>
      </Section>
    </Layout>
  );
}

export const text = (email: ReminderEmailData): string => {
  const openUrl = `${email.baseUrl}/a#t=${email.token}`;
  const deliveryUrl = `${email.baseUrl}/delivery?token=${email.token}`;

  const ratingLines: Array<string> = [];
  if (email.ratingQuestion) {
    ratingLines.push(email.ratingQuestion.text, "");
    for (let val = 1; val <= 5; val++) {
      const label =
        val === 1
          ? `1 (${email.ratingQuestion.lowLabel})`
          : val === 5
            ? `5 (${email.ratingQuestion.highLabel})`
            : `${val}`;
      ratingLines.push(`${label}: ${email.baseUrl}/a#t=${email.token}&v=${val}`);
    }
    ratingLines.push("");
  }

  const actionLines: Array<string> = [];
  if (email.actions.length > 0) {
    actionLines.push(message("invitation.actionsHeading"));
    for (const act of email.actions.slice(0, 3)) {
      actionLines.push(`• ${act}`);
    }
    actionLines.push("");
  }

  return textLayout(
    [
      message("reminder.heading", { pulse: email.pulseName }),
      "",
      message("reminder.body"),
      "",
      ...ratingLines,
      `${message("invitation.openCheckIn")}: ${openUrl}`,
      "",
      ...actionLines,
      `${message("invitation.changeWhen")}: ${deliveryUrl}`,
      `${message("reminder.unsubscribe")}: ${email.unsubscribeUrl}`,
      message("invitation.personalNotice"),
    ],
    message("invitation.reason"),
  );
};
